<student_code untrusted="true">
=== wrong_baud.ino ===
   1| // Lab 4 - button toggles LED, prints state on Serial1
   2| 
   3| #define BUTTON 2
   4| #define LED LED_BUILTIN
   5| #define DEBOUNCE_TIME 5   // ms
   6| 
   7| bool lightOn = false;
   8| bool wasPressed = false;
   9| unsigned long pressStart = 0;
  10| bool counted = false;
  11| 
  12| void setup() {
  13|   pinMode(BUTTON, INPUT_PULLUP);
  14|   pinMode(LED, OUTPUT);
  15|   digitalWrite(LED, LOW);
  16|   Serial1.begin(115200);
  17| }
  18| 
  19| void loop() {
  20|   bool pressed = digitalRead(BUTTON) == LOW;
  21| 
  22|   if (pressed && !wasPressed) {
  23|     pressStart = millis();   // contact just closed (or bounced)
  24|     counted = false;
  25|   }
  26|   if (!pressed) {
  27|     counted = false;
  28|   }
  29| 
  30|   if (pressed && !counted && millis() - pressStart >= DEBOUNCE_TIME) {
  31|     counted = true;
  32|     lightOn = !lightOn;
  33|     digitalWrite(LED, lightOn);
  34|     Serial1.println(lightOn ? "ON" : "OFF");
  35|   }
  36| 
  37|   wasPressed = pressed;
  38| }
</student_code>
